122	// ---------------------------------------------------------------------------
123	// SpendLimitService (exportado)
124	// ---------------------------------------------------------------------------
125	
126	export const SpendLimitService = {
127	  // -------------------------------------------------------------------------
128	  // CRUD — teto de gasto
129	  // -------------------------------------------------------------------------
130	
131	  /**
132	   * Busca o teto de gasto mensal da empresa. Retorna null se não configurado.
133	   * scope '' (string vazia) = empresa inteira (NOT NULL DEFAULT '' — v1 single-store).
134	   */
135	  async getSpendLimit(companyId: string, scope: string = ''): Promise<SpendLimit | null> {
136	    try {
137	      const { data, error } = await supabase
138	        .from('company_spend_limits')
139	        .select('*')
140	        .eq('company_id', companyId)
141	        .eq('period', 'month')
142	        .eq('scope', scope)
143	        .maybeSingle();
144	      if (error) {
145	        logError('spendLimit.getSpendLimit', error);
146	        return null;
147	      }
148	      return (data as SpendLimit) ?? null;
149	    } catch (err) {
150	      logError('spendLimit.getSpendLimit', err);
151	      return null;
152	    }
153	  },
154	
155	  /**
156	   * Cria ou atualiza o teto de gasto mensal da empresa (upsert idempotente).
157	   * Usa ON CONFLICT (company_id, period, scope) — scope NOT NULL DEFAULT ''.
158	   * scope = '' → teto da empresa inteira (v1 single-store).
159	   *
160	   * @returns SpendLimit atualizado ou null em caso de erro.
161	   */
162	  async upsertSpendLimit(
163	    companyId: string,
164	    params: {
165	      amount: number;
166	      alertThresholds?: number[];
167	      scope?: string;
168	      financialContactEmail?: string | null;
169	      financialContactPhone?: string | null;
170	    },
171	  ): Promise<SpendLimit | null> {
172	    try {
173	      const payload: Record<string, unknown> = {
174	        company_id: companyId,
175	        period: 'month',
176	        amount: params.amount,
177	        scope: params.scope ?? '',
178	      };
179	      if (params.alertThresholds !== undefined) {
180	        payload.alert_thresholds = params.alertThresholds;
181	      }
182	      if (params.financialContactEmail !== undefined) {
183	        payload.financial_contact_email = params.financialContactEmail;
184	      }
185	      if (params.financialContactPhone !== undefined) {
186	        payload.financial_contact_phone = params.financialContactPhone;
187	      }
188	
189	      const { data, error } = await supabase
190	        .from('company_spend_limits')
191	        .upsert(payload, { onConflict: 'company_id,period,scope' })
192	        .select()
193	        .single();
194	
195	      if (error) {
196	        logError('spendLimit.upsertSpendLimit', error);
197	        return null;
198	      }
199	      return data as SpendLimit;
200	    } catch (err) {
201	      logError('spendLimit.upsertSpendLimit', err);
202	      return null;
203	    }
204	  },
205	
206	  // -------------------------------------------------------------------------
207	  // CRUD — faturamento mensal
208	  // -------------------------------------------------------------------------
209	
210	  /**
211	   * Busca o faturamento declarado da empresa em um mês (year_month = DATE no dia 1).
212	   * Normaliza para o primeiro dia do mês automaticamente.
213	   *
214	   * @param yearMonth Date ou string YYYY-MM-DD (sempre normalizada para o dia 1).
215	   */
216	  async getMonthlyRevenue(
217	    companyId: string,
218	    yearMonth: Date | string,
219	  ): Promise<MonthlyRevenue | null> {
220	    try {
221	      const ym =
222	        typeof yearMonth === 'string'
223	          ? yearMonth.slice(0, 7) + '-01'
224	          : monthStart(yearMonth);
225	
226	      const { data, error } = await supabase
227	        .from('company_monthly_revenue')
228	        .select('*')
229	        .eq('company_id', companyId)
230	        .eq('year_month', ym)
231	        .maybeSingle();
232	
233	      if (error) {
234	        logError('spendLimit.getMonthlyRevenue', error);
235	        return null;
236	      }
237	      return (data as MonthlyRevenue) ?? null;
238	    } catch (err) {
239	      logError('spendLimit.getMonthlyRevenue', err);
240	      return null;
241	    }
242	  },
243	
244	  /**
245	   * Cria ou atualiza o faturamento declarado do mês (upsert idempotente).
246	   * Normaliza year_month para o primeiro dia do mês.
247	   *
248	   * @param yearMonth Date ou string YYYY-MM-DD.
249	   * @param amount    Faturamento bruto BRL (>= 0).
250	   */
251	  async upsertMonthlyRevenue(
252	    companyId: string,
253	    yearMonth: Date | string,
254	    amount: number,
255	  ): Promise<MonthlyRevenue | null> {
256	    try {
257	      const ym =
258	        typeof yearMonth === 'string'
259	          ? yearMonth.slice(0, 7) + '-01'
260	          : monthStart(yearMonth);
261	
262	      const { data, error } = await supabase
263	        .from('company_monthly_revenue')
264	        .upsert(
265	          { company_id: companyId, year_month: ym, amount },
266	          { onConflict: 'company_id,year_month' },
267	        )
268	        .select()
269	        .single();
270	
271	      if (error) {
272	        logError('spendLimit.upsertMonthlyRevenue', error);
273	        return null;
274	      }
275	      return data as MonthlyRevenue;
276	    } catch (err) {
277	      logError('spendLimit.upsertMonthlyRevenue', err);
278	      return null;
279	    }
280	  },
281	
282	  // -------------------------------------------------------------------------
283	  // Avaliação do alerta de teto (R12)
284	  // -------------------------------------------------------------------------
285	
286	  /**
287	   * Avalia se o gasto acumulado do mês corrente cruzou algum threshold do teto.
288	   * Insere alerta idempotente em `notifications` para o MAIOR threshold cruzado
289	   * ainda não alertado no período.
290	   *
291	   * Regras (spec Slice 3 — contrato de ALERTA):
292	   *  - Dispara apenas o MAIOR threshold cruzado não-alertado (ex.: cruzou 92% → alerta 90%, não 80%).
293	   *  - Threshold >100% usa chave 'OVER'.
294	   *  - Idempotência: verifica SELECT LIMIT 1 por link antes do INSERT.
295	   *  - NUNCA bloqueia contratação (exceções capturadas silenciosamente — best-effort).
296	   *  - NÃO chama dentro de RPC de saldo (Article 8).
297	   *
298	   * @param companyId   UUID da empresa (= auth.uid() da empresa = wallets.user_id).
299	   * @param now         Data de referência (default: Date.now()). Injetável para testes.
300	   */
301	  async evaluateSpendAlert(companyId: string, now: Date = new Date()): Promise<void> {
302	    try {
303	      // 1. Buscar o teto configurado (scope = '' → empresa inteira, v1)
304	      const limit = await SpendLimitService.getSpendLimit(companyId);
305	      if (!limit || limit.amount <= 0) return; // Sem teto configurado → nada a fazer
306	
307	      // 2. Calcular gasto acumulado do período
308	      const spend = await computeAccumulatedSpend(companyId, now);
309	      if (!spend) return; // Erro de query → best-effort, não bloqueia
310	
311	      const { totalAmount } = spend;
312	      const percent = (totalAmount / limit.amount) * 100;
313	
314	      // 3. Determinar o maior threshold cruzado
315	      //    Inclui 'OVER' se gasto > teto (>100%)
316	      const thresholds = [...(limit.alert_thresholds ?? [80, 90, 100])].sort((a, b) => a - b);
317	
318	      let highestCrossed: number | 'OVER' | null = null;
319	
320	      if (percent > 100) {
321	        highestCrossed = 'OVER';
322	      } else {
323	        for (const t of thresholds) {
324	          if (percent >= t) {
325	            highestCrossed = t;
326	          }
327	        }
328	      }
329	
330	      if (highestCrossed === null) return; // Nenhum threshold cruzado
331	
332	      // 4. Construir a chave de idempotência
333	      const periodKey = yyyymm(now);
334	      const thresholdKey = highestCrossed === 'OVER' ? 'OVER' : String(highestCrossed);
335	      const alertLink = `/company/financeiro?alert=${companyId}:${periodKey}:${thresholdKey}`;
336	
337	      // 5. Resolver o owner da empresa (user_id para a notificação)
338	      //    Usa o financial_contact_email se disponível, mas notificação in-app vai pro owner.
339	      const { data: companyRow, error: companyErr } = await supabase
340	        .from('companies')
341	        .select('owner_id')
342	        .eq('id', companyId)
343	        .maybeSingle();
344	
345	      if (companyErr || !companyRow) {
346	        logError('spendLimit.evaluateSpendAlert.company', companyErr ?? new Error('company not found'));
347	        return;
348	      }
349	      const ownerId = companyRow.owner_id as string;
350	
351	      // 6. Verificar idempotência: já existe alerta com este link?
352	      //    notifications_user_id_idx cobre user_id (sem full-scan).
353	      const { data: existing, error: checkErr } = await supabase
354	        .from('notifications')
355	        .select('id')
356	        .eq('user_id', ownerId)
357	        .eq('link', alertLink)
358	        .limit(1)
359	        .maybeSingle();
360	
361	      if (checkErr) {
362	        logError('spendLimit.evaluateSpendAlert.check', checkErr);
363	        return;
364	      }
365	      if (existing) return; // Alerta já enviado → idempotência
366	
367	      // 7. Compor mensagem do alerta
368	      const percentFormatted = Math.round(percent);
369	      const amountFormatted = totalAmount.toLocaleString('pt-BR', {
370	        style: 'currency',
371	        currency: 'BRL',
372	      });
373	      const limitFormatted = limit.amount.toLocaleString('pt-BR', {
374	        style: 'currency',
375	        currency: 'BRL',
376	      });
377	
378	      let title: string;
379	      let message: string;
380	
381	      if (highestCrossed === 'OVER') {
382	        title = 'Teto de gasto ultrapassado';
383	        message =
384	          `Gasto mensal de ${amountFormatted} ultrapassou o teto de ${limitFormatted} ` +
385	          `(${percentFormatted}%). As contratações continuam funcionando normalmente.`;
386	      } else {
387	        title = `Alerta: ${highestCrossed}% do teto de gasto atingido`;
388	        message =
389	          `Gasto mensal de ${amountFormatted} atingiu ${percentFormatted}% do teto de ` +
390	          `${limitFormatted}. As contratações continuam funcionando normalmente.`;
391	      }
392	
393	      // 8. Inserir notificação in-app
394	      const { error: insertErr } = await supabase.from('notifications').insert({
395	        user_id: ownerId,
396	        type: 'payment',
397	        title,
398	        message,
399	        link: alertLink,
400	      });
401	
402	      if (insertErr) {
403	        logError('spendLimit.evaluateSpendAlert.insert', insertErr);
404	        // Best-effort — não propaga o erro para não quebrar o pagamento
405	      }
406	    } catch (err) {
407	      // NUNCA propaga — alerta é best-effort (spec: "Alerta NUNCA bloqueia")
408	      logError('spendLimit.evaluateSpendAlert', err);
409	    }
410	  },
411	};
