1	/**
2	 * FinancialBIService — inteligência financeira da empresa (Slice 3, R13-R16).
3	 *
4	 * Implementa 4 queries derivadas de BI sobre escrow_transactions + jobs + applications.
5	 * Nenhuma view criada (decisão do architect: views não propagam RLS com segurança — spec Slice 3).
6	 *
7	 * BI-2: Gasto e horas por freela (real: checkout-checkin; fallback: jobs.estimated_hours).
8	 * BI-3: Ratio custo/hora + custo-%-faturamento (oculto se mês sem faturamento informado).
9	 * BI-4: Custo de no-show — heurística v1, ROTULADO COMO ESTIMATIVA.
10	 * BI-5: Flag de concentração de horas/dias por freela (risco de vínculo trabalhista).
11	 *
12	 * Contratos de dados (spec Slice 3):
13	 *  - Gasto = escrow_transactions WHERE status IN ('released','captured').
14	 *  - Carimbo: COALESCE(captured_at, released_at, created_at) — filtrar o mês por este.
15	 *  - Empresa da linha: company_wallet_id → wallets.user_id = companyId.
16	 *  - Freela: worker_wallet_id → wallets.user_id | application_id → applications.worker_id.
17	 *
18	 * Padrões do projeto:
19	 *  - supabase.from direto (Art. 5 — sem React Query).
20	 *  - Tipos à mão em types/index.ts (Art. 2).
21	 *  - Imports relativos (sem alias @/).
22	 *  - logError (nunca console.log).
23	 */
24	
25	import { supabase } from '../lib/supabase';
26	import { logError } from '../lib/logger';
27	import type {
28	  AccumulatedSpend,
29	  SpendByWorker,
30	  CostRatio,
31	  NoShowCost,
32	  ConcentrationFlag,
33	} from '../types';
34	
35	// ---------------------------------------------------------------------------
36	// Constantes de produto (BI-5 — limiar de concentração)
37	// Calibrar aqui sem migration.
38	// ---------------------------------------------------------------------------
39	
40	/** Horas totais no período que sinalizam risco de vínculo. */
41	const CONCENTRATION_HOURS_THRESHOLD = 150;
42	
43	/** Dias distintos no período que, combinados com as horas, sinalizam risco de vínculo. */
44	const CONCENTRATION_DAYS_THRESHOLD = 20;
45	
46	// ---------------------------------------------------------------------------
47	// Helpers de período
48	// ---------------------------------------------------------------------------
49	
50	export interface BIPeriod {
51	  /** Primeiro dia do mês (inclusive), ISO date string YYYY-MM-DD. */
52	  start: string;
53	  /** Primeiro dia do mês seguinte (exclusive), ISO date string YYYY-MM-DD. */
54	  end: string;
55	}
56	
57	/** Retorna o período do mês corrente. */
58	export function currentMonthPeriod(now: Date = new Date()): BIPeriod {
59	  const y = now.getFullYear();
60	  const m = String(now.getMonth() + 1).padStart(2, '0');
61	  const start = `${y}-${m}-01`;
62	  const next = new Date(y, now.getMonth() + 1, 1);
63	  const ny = next.getFullYear();
64	  const nm = String(next.getMonth() + 1).padStart(2, '0');
65	  const end = `${ny}-${nm}-01`;
66	  return { start, end };
67	}
68	
69	/** Retorna um período customizado a partir de strings ISO date. */
70	export function customPeriod(start: string, end: string): BIPeriod {
71	  return { start, end };
72	}
73	
74	// ---------------------------------------------------------------------------
75	// Tipos internos de linha bruta de escrow
76	// ---------------------------------------------------------------------------
77	
78	interface EscrowRow {
79	  amount: number;
80	  captured_at: string | null;
81	  released_at: string | null;
82	  created_at: string;
83	  application_id: string | null;
84	  worker_wallet_id: string | null;
85	  job_id: string | null;
86	}
87	
88	interface ApplicationRow {
89	  id: string;
90	  worker_id: string;
91	  job_id: string;
92	  status: string;
93	  worker_checkin_at: string | null;
94	  worker_checkout_at: string | null;
95	  invitation_response: string | null;
96	  invitation_expires_at: string | null;
97	}
98	
99	interface JobRow {
100	  id: string;
101	  start_date: string;
102	  estimated_hours: number | null;
103	}
104	
105	interface WorkerProfileRow {
106	  id: string;
107	  full_name: string;
108	  avatar_url: string | null;
109	  photo_url: string | null;
110	}
111	
112	// ---------------------------------------------------------------------------
113	// Helper: buscar wallet_id da empresa
114	// ---------------------------------------------------------------------------
115	
116	async function getCompanyWalletId(companyId: string): Promise<string | null> {
117	  const { data, error } = await supabase
118	    .from('wallets')
119	    .select('id')
120	    .eq('user_id', companyId)
121	    .maybeSingle();
122	  if (error) {
123	    logError('financialBI.getCompanyWalletId', error);
124	    return null;
125	  }
126	  return (data?.id as string | null) ?? null;
127	}
128	
129	// ---------------------------------------------------------------------------
130	// Helper: filtrar linha de escrow pelo período (JS-side, PostgREST não suporta COALESCE)
131	// ---------------------------------------------------------------------------
132	
133	function isInPeriod(row: EscrowRow, startDate: Date, endDate: Date): boolean {
134	  const stamp = new Date(
135	    row.captured_at ?? row.released_at ?? row.created_at,
136	  );
137	  return stamp >= startDate && stamp < endDate;
138	}
139	
140	// ---------------------------------------------------------------------------
141	// FinancialBIService (exportado)
142	// ---------------------------------------------------------------------------
143	
144	export const FinancialBIService = {
145	  // -------------------------------------------------------------------------
146	  // BI-1: Gasto acumulado do período
147	  // -------------------------------------------------------------------------
148	
149	  /**
150	   * Computa o gasto acumulado da empresa no período (BI-1).
151	   * Fonte: escrow_transactions WHERE status IN ('released','captured'),
152	   * filtrado pelo carimbo COALESCE(captured_at, released_at, created_at).
153	   */
154	  async getAccumulatedSpend(companyId: string, period: BIPeriod): Promise<AccumulatedSpend> {
155	    const empty: AccumulatedSpend = {
156	      totalAmount: 0,
157	      periodStart: period.start,
158	      periodEnd: period.end,
159	    };
160	
161	    try {
162	      const walletId = await getCompanyWalletId(companyId);
163	      if (!walletId) return empty;
164	
165	      const { data: rows, error } = await supabase
166	        .from('escrow_transactions')
167	        .select('amount, captured_at, released_at, created_at')
168	        .eq('company_wallet_id', walletId)
169	        .in('status', ['released', 'captured']);
170	
171	      if (error) {
172	        logError('financialBI.getAccumulatedSpend', error);
173	        return empty;
174	      }
175	
176	      const startDate = new Date(period.start);
177	      const endDate = new Date(period.end);
178	      let totalAmount = 0;
179	
180	      for (const row of (rows ?? []) as EscrowRow[]) {
181	        if (isInPeriod(row, startDate, endDate)) {
182	          totalAmount += Number(row.amount ?? 0);
183	        }
184	      }
185	
186	      return { totalAmount, periodStart: period.start, periodEnd: period.end };
187	    } catch (err) {
188	      logError('financialBI.getAccumulatedSpend', err);
189	      return empty;
190	    }
191	  },
192	
193	  // -------------------------------------------------------------------------
194	  // BI-2: Gasto e horas por freela no período
195	  // -------------------------------------------------------------------------
196	
197	  /**
198	   * Gasto e horas por freela no período (BI-2).
199	   *
200	   * Horas reais quando houver worker_checkout_at e worker_checkin_at em applications.
201	   * Fallback: jobs.estimated_hours do turno concluído.
202	   * hoursSource = 'real' | 'estimated' | 'mixed' (por freela no período).
203	   *
204	   * Agrupa por worker_id (via application_id → applications.worker_id).
205	   */
206	  async getSpendByWorker(companyId: string, period: BIPeriod): Promise<SpendByWorker[]> {
207	    try {
208	      const walletId = await getCompanyWalletId(companyId);
209	      if (!walletId) return [];
210	
211	      // 1. Linhas de escrow no período (com application_id para join)
212	      const { data: escrowRows, error: escrowErr } = await supabase
213	        .from('escrow_transactions')
214	        .select('amount, captured_at, released_at, created_at, application_id, job_id')
215	        .eq('company_wallet_id', walletId)
216	        .in('status', ['released', 'captured'])
217	        .not('application_id', 'is', null);
218	
219	      if (escrowErr) {
220	        logError('financialBI.getSpendByWorker.escrow', escrowErr);
221	        return [];
222	      }
223	
224	      const startDate = new Date(period.start);
225	      const endDate = new Date(period.end);
226	
227	      // Filtrar pelo período
228	      const inPeriod = ((escrowRows ?? []) as EscrowRow[]).filter((r) =>
229	        isInPeriod(r, startDate, endDate),
230	      );
231	
232	      if (inPeriod.length === 0) return [];
233	
234	      // 2. Buscar applications (check-in/out + worker_id) para os application_ids do período
235	      const appIds = [...new Set(inPeriod.map((r) => r.application_id as string))];
236	      const jobIds = [...new Set(inPeriod.map((r) => r.job_id).filter(Boolean) as string[])];
237	
238	      const [appResult, jobResult] = await Promise.all([
239	        supabase
240	          .from('applications')
241	          .select('id, worker_id, job_id, worker_checkin_at, worker_checkout_at, status')
242	          .in('id', appIds),
243	        jobIds.length > 0
244	          ? supabase
245	              .from('jobs')
246	              .select('id, estimated_hours')
247	              .in('id', jobIds)
248	          : Promise.resolve({ data: [], error: null }),
249	      ]);
250	
251	      if (appResult.error) {
252	        logError('financialBI.getSpendByWorker.apps', appResult.error);
253	        return [];
254	      }
255	      if (jobResult.error) {
256	        logError('financialBI.getSpendByWorker.jobs', jobResult.error);
257	      }
258	
259	      const appMap = new Map<string, ApplicationRow>(
260	        ((appResult.data ?? []) as ApplicationRow[]).map((a) => [a.id, a]),
261	      );
262	      const jobMap = new Map<string, JobRow>(
263	        ((jobResult.data ?? []) as JobRow[]).map((j) => [j.id, j]),
264	      );
265	
266	      // Coletar worker_ids únicos
267	      const workerIds = [...new Set(
268	        appIds
269	          .map((aid) => appMap.get(aid)?.worker_id)
270	          .filter(Boolean) as string[],
271	      )];
272	
273	      if (workerIds.length === 0) return [];
274	
275	      // 3. Buscar perfis dos workers
276	      const { data: workers, error: workerErr } = await supabase
277	        .from('workers')
278	        .select('id, full_name, avatar_url, photo_url')
279	        .in('id', workerIds);
280	
281	      if (workerErr) {
282	        logError('financialBI.getSpendByWorker.workers', workerErr);
283	      }
284	
285	      const workerMap = new Map<string, WorkerProfileRow>(
286	        ((workers ?? []) as WorkerProfileRow[]).map((w) => [w.id, w]),
287	      );
288	
289	      // 4. Agregar por worker
290	      interface WorkerAgg {
291	        totalAmount: number;
292	        totalHours: number;
293	        realHoursCount: number;
294	        estimatedHoursCount: number;
295	        shiftsCount: number;
296	      }
297	
298	      const agg = new Map<string, WorkerAgg>();
299	
300	      for (const row of inPeriod) {
301	        const app = appMap.get(row.application_id as string);
302	        if (!app) continue;
303	
304	        const workerId = app.worker_id;
305	        if (!agg.has(workerId)) {
306	          agg.set(workerId, {
307	            totalAmount: 0,
308	            totalHours: 0,
309	            realHoursCount: 0,
310	            estimatedHoursCount: 0,
311	            shiftsCount: 0,
312	          });
313	        }
314	        const entry = agg.get(workerId)!;
315	        entry.totalAmount += Number(row.amount ?? 0);
316	        entry.shiftsCount += 1;
317	
318	        // Horas: real se houver check-in/out; fallback estimated_hours
319	        if (app.worker_checkin_at && app.worker_checkout_at) {
320	          const hours =
321	            (new Date(app.worker_checkout_at).getTime() -
322	              new Date(app.worker_checkin_at).getTime()) /
323	            3_600_000;
324	          entry.totalHours += hours;
325	          entry.realHoursCount += 1;
326	        } else {
327	          const job = row.job_id ? jobMap.get(row.job_id) : undefined;
328	          const estimated = job?.estimated_hours ?? 0;
329	          entry.totalHours += estimated;
330	          entry.estimatedHoursCount += 1;
331	        }
332	      }
333	
334	      // 5. Montar resultado
335	      const result: SpendByWorker[] = [];
336	      for (const [workerId, data] of agg.entries()) {
337	        const worker = workerMap.get(workerId);
338	        let hoursSource: SpendByWorker['hoursSource'] = 'estimated';
339	        if (data.realHoursCount > 0 && data.estimatedHoursCount === 0) {
340	          hoursSource = 'real';
341	        } else if (data.realHoursCount > 0 && data.estimatedHoursCount > 0) {
342	          hoursSource = 'mixed';
343	        }
344	
345	        result.push({
346	          workerId,
347	          workerName: worker?.full_name ?? 'Worker',
348	          workerAvatarUrl: worker?.avatar_url ?? worker?.photo_url ?? null,
349	          totalAmount: data.totalAmount,
350	          totalHours: data.totalHours,
351	          hoursSource,
352	          shiftsCount: data.shiftsCount,
353	        });
354	      }
355	
356	      // Ordenar por gasto descendente
357	      result.sort((a, b) => b.totalAmount - a.totalAmount);
358	      return result;
359	    } catch (err) {
360	      logError('financialBI.getSpendByWorker', err);
361	      return [];
362	    }
363	  },
