61	export function useSpendLimit(yearMonth?: Date | string): UseSpendLimitResult {
62	  const [spendLimit, setSpendLimit] = useState<SpendLimit | null>(null);
63	  const [monthlyRevenue, setMonthlyRevenue] = useState<MonthlyRevenue | null>(null);
64	  const [loading, setLoading] = useState(true);
65	  const [error, setError] = useState<string | null>(null);
66	  const [companyId, setCompanyId] = useState<string | null>(null);
67	  const navigate = useNavigate();
68	
69	  // Mês de referência estável
70	  const refMonth: Date | string = yearMonth ?? new Date();
71	
72	  const load = useCallback(
73	    async (cid?: string) => {
74	      try {
75	        const {
76	          data: { user },
77	        } = await supabase.auth.getUser();
78	        if (!user) {
79	          navigate('/login');
80	          return;
81	        }
82	
83	        setLoading(true);
84	        setError(null);
85	
86	        let resolvedCompanyId = cid ?? companyId;
87	        if (!resolvedCompanyId) {
88	          const { data: company, error: cErr } = await supabase
89	            .from('companies')
90	            .select('id')
91	            .eq('owner_id', user.id)
92	            .maybeSingle();
93	          if (cErr) {
94	            logError('useSpendLimit.load.company', cErr);
95	            setError('Erro ao carregar dados da empresa.');
96	            setLoading(false);
97	            return;
98	          }
99	          if (!company) {
100	            setLoading(false);
101	            return;
102	          }
103	          resolvedCompanyId = company.id as string;
104	          setCompanyId(resolvedCompanyId);
105	        }
106	
107	        const [limit, revenue] = await Promise.all([
108	          SpendLimitService.getSpendLimit(resolvedCompanyId),
109	          SpendLimitService.getMonthlyRevenue(resolvedCompanyId, refMonth),
110	        ]);
111	
112	        setSpendLimit(limit);
113	        setMonthlyRevenue(revenue);
114	      } catch (err) {
115	        logError('useSpendLimit.load', err);
116	        setError('Erro ao carregar dados financeiros.');
117	      } finally {
118	        setLoading(false);
119	      }
120	    },
121	    // eslint-disable-next-line react-hooks/exhaustive-deps
122	    [navigate, companyId],
123	  );
124	
125	  useEffect(() => {
126	    let active = true;
127	    void (async () => {
128	      const {
129	        data: { user },
130	      } = await supabase.auth.getUser();
131	      if (!user) {
132	        navigate('/login');
133	        return;
134	      }
135	
136	      setLoading(true);
