138	
139	      const { data: company, error: cErr } = await supabase
140	        .from('companies')
141	        .select('id')
142	        .eq('owner_id', user.id)
143	        .maybeSingle();
144	
145	      if (cErr || !company) {
146	        if (active) {
147	          setLoading(false);
148	          if (cErr) setError('Erro ao carregar dados da empresa.');
149	        }
150	        return;
151	      }
152	
153	      const cid = company.id as string;
154	      if (active) setCompanyId(cid);
155	
156	      const [limit, revenue] = await Promise.all([
157	        SpendLimitService.getSpendLimit(cid),
158	        SpendLimitService.getMonthlyRevenue(cid, refMonth),
159	      ]);
160	
161	      if (!active) return;
162	      setSpendLimit(limit);
163	      setMonthlyRevenue(revenue);
164	      setLoading(false);
165	    })();
166	    return () => {
167	      active = false;
168	    };
169	    // eslint-disable-next-line react-hooks/exhaustive-deps
170	  }, [navigate]);
171	
172	  const upsertSpendLimit = useCallback(
173	    async (params: {
174	      amount: number;
175	      alertThresholds?: number[];
176	      financialContactEmail?: string | null;
177	      financialContactPhone?: string | null;
178	    }): Promise<boolean> => {
179	      if (!companyId) return false;
180	      const result = await SpendLimitService.upsertSpendLimit(companyId, params);
181	      if (!result) return false;
182	      setSpendLimit(result);
183	      return true;
184	    },
185	    [companyId],
186	  );
187	
188	  const upsertMonthlyRevenue = useCallback(
189	    async (amount: number, ym?: Date | string): Promise<boolean> => {
190	      if (!companyId) return false;
191	      const result = await SpendLimitService.upsertMonthlyRevenue(
192	        companyId,
193	        ym ?? refMonth,
194	        amount,
195	      );
196	      if (!result) return false;
197	      setMonthlyRevenue(result);
198	      return true;
199	    },
200	    // eslint-disable-next-line react-hooks/exhaustive-deps
201	    [companyId],
202	  );
203	
204	  return {
205	    spendLimit,
206	    monthlyRevenue,
207	    loading,
208	    error,
209	    upsertSpendLimit,
210	    upsertMonthlyRevenue,
211	    refresh: () => void load(),
212	  };
213	}
